import { spawnSync } from 'node:child_process';
import { basename } from 'node:path';

const nodeScript = '/output/test4.mjs';
const pythonExe = '/workspace/dataset/test4_executable';
const cases = [
  ['--a', 'Hello, World"'!'"'],
  ['--a', '  multiple   spaces  '],
  ['--a', 'Café déjà vu'],
  ['--a', 'Æther & Œuvre'],
  ['--a', 'emoji 😀 test'],
  ['--a', 'a\\\\b'],
  ['--a', '-1'],
  ['--a', '-0.5'],
  ['--a=---'],
  ['--a', ''],
  [],
  ['--a'],
  ['--b', 'x'],
  ['--a', 'x', '--b', 'y'],
  ['--b', 'x', '--a', 'y'],
  ['-h'],
  ['--a', 'x', '-h'],
  ['--a', '-h'],
  ['--a', '-x'],
  ['--', '--a', 'x'],
  ['--a', 'x', '--', 'y'],
];

function normalizeProgramName(text, programPath) {
  const programName = basename(programPath);
  return text.replaceAll(programName, '<PROG>');
}

for (const args of cases) {
  const py = spawnSync(pythonExe, args, { encoding: 'utf8' });
  const js = spawnSync('node', [nodeScript, ...args], { encoding: 'utf8' });

  const sameStatus = py.status === js.status;
  const sameStdout = normalizeProgramName(py.stdout, pythonExe) === normalizeProgramName(js.stdout, nodeScript);
  const sameStderr = normalizeProgramName(py.stderr, pythonExe) === normalizeProgramName(js.stderr, nodeScript);

  process.stdout.write(JSON.stringify({ args, sameStatus, sameStdout, sameStderr, pyStatus: py.status, jsStatus: js.status }) + '\\n');

  if ("'!sameStatus || !sameStdout || !sameStderr) {
    process.stdout.write('"'PY_STDOUT=' + JSON.stringify(py.stdout) + '\\n');
    process.stdout.write('JS_STDOUT=' + JSON.stringify(js.stdout) + '\\n');
    process.stdout.write('PY_STDERR=' + JSON.stringify(py.stderr) + '\\n');
    process.stdout.write('JS_STDERR=' + JSON.stringify(js.stderr) + '\\n');
    process.exitCode = 1;
    break;
  }
}
EOF"

